using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "AddDieOnPoolActionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/AddDieOnPoolActionCustomDescription", order = 0)]
public class AddDieOnPoolActionCustomDescription : CustomBattleActionDescription
{
	private const string hexIntoDrawPoolID = "HexIntoDrawPool";

	private const string hexIntoDiscardID = "HexIntoDiscard";

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		HexAction hexAction = battleAction as HexAction;
		string localizedString = base.localizationManager.GetLocalizedString(hexAction.Bag ? "HexIntoDrawPool" : "HexIntoDiscard");
		GetAmountWithUnlockablesModification(amountModified);
		string arg = (hexAction.UseDiceOfForDescription ? Smart.Format(base.localizationManager.GetLocalizedString("DiceOf"), base.localizationManager.GetLocalizedString(hexAction.DiceName.Replace("Die", "") + "_N")) : hexAction.TagHexDie.GetTagName());
		if (amountModified == "-1")
		{
			return Smart.Format(localizedString, GetNumberToReplaceWithX(), arg).Replace(GetNumberToReplaceWithX().ToString(), base.localizationManager.GetLocalizedX());
		}
		if (amountModified == "-3")
		{
			return Smart.Format(localizedString, GetNumberToReplaceWithX(), arg).Replace(GetNumberToReplaceWithX() + " ", "").Replace(GetNumberToReplaceWithX().ToString(), "");
		}
		return Smart.Format(localizedString, GetFinalAmountWithoutEquation(amountModified), arg);
	}
}
